    public int[] sortedSquares(int[] nums) {
        int n = nums.length;
        int[] res = new int[n];
        int l = 0, r = n - 1, idx = n - 1;
        while (l <= r) {
            int sqL = nums[l] * nums[l];
            int sqR = nums[r] * nums[r];
            if (sqL > sqR) { res[idx--] = sqL; l++; }
            else { res[idx--] = sqR; r--; }
        }
        return res;
    }
