            int temp = nums[i]; nums[i] = nums[j]; nums[j] = temp;
        }
        reverse(nums, i + 1, nums.length - 1);
    }
    private void reverse(int[] nums, int l, int r) {
        while (l < r) {
            int temp = nums[l]; nums[l] = nums[r]; nums[r] = temp;
            l++; r--;
        }
    }
